liation_lines x JOIN fee_reconciliation_batches b ON b.id=x.batch_id AND b.school_id=x.school_id WHERE x.school_id=l.school_id AND x.matched_ledger_id=l.id AND x.match_status='matched') ORDER BY (l.reference=?) DESC,l.created_at DESC LIMIT 30");$q->execute([$school,$row['amount'],$row['transaction_date'],$row['transaction_date'],$row['reference']]);reconciliation_json(200,['ok'=>true,'data'=>['line'=>$row,'candidates'=>$q->fetchAll()]]);}reconciliation_json(422,['ok'=>false,'message'=>'Unknown reconciliation view.']);}
