 if($action==='import'){$name=trim((string)($_POST['statement_name']??''));$date=trim((string)($_POST['statement_date']??''));$statementDate=DateTimeImmutable::createFromFormat('!Y-m-d',$date);$file=$_FILES['statement_csv']??null;if($name===''||mb_strlen($name)>180||!$statementDate||$statementDate->format('Y-m-d')!==$date||!$file||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||(int)$file['size']>5*1024*1024)throw new DomainException('Enter a statement name and date, and upload a CSV no larger than 5 MB.');$fp=fopen((string)$file['tmp_name'],'rb');if(!$fp)throw new DomainException('The CSV file could not be read.');$header=fgetcsv($fp,4096,',','"','\\');$header=array_map(static fn($v)=>strtolower(trim((string)$v, " \t\n\r\0\x0B\xEF\xBB\xBF")),is_array($header)?$header:[]);$required=['date','amount','reference'];foreach($required as $column)if(!in_array($column,$header,true)){fclose($fp);throw new DomainException('CSV header must include date, amount, reference, and optionally description.');}$ix=array_flip($header);$rows=[];$lineNo=1;while(($row=fgetcsv($fp,4096,',','"','\\'))!==false){$lineNo++;if(count($rows)>=1000){fclose($fp);throw new DomainException('A statement may contain at most 1,000 transaction rows.');}if(count($row)===1&&trim((string)$row[0])==='')continue;$rawDate=trim((string)($row[$ix['date']]??''));$parsed=DateTimeImmutable::createFromFormat('!Y-m-d',$rawDate);if(!$parsed||$parsed->format('Y-m-d')!==$rawDate){$parsed=DateTimeImmutable::createFromFormat('!d/m/Y',$rawDate);if($parsed&&$parsed->format('d/m/Y')!==$rawDate)$parsed=false;}$amount=filter_var(trim((string)($row[$ix['amount']]??'')),FILTER_VALIDATE_FLOAT);$reference=trim((string)($row[$ix['reference']]??''));$description=isset($ix['description'])?trim((string)($row[$ix['description']]??'')):'';if(!$parsed||$amount===false||$amount<=0||$amount>100000000||$reference===''||mb_strlen($reference)>100||mb_strlen($description)>255){fclose($fp);throw new DomainException('CSV row '.$lineNo.' has an invalid date, positive amount, reference, or description.');}$rows[]=['line'=>$lineNo-1,'date'=>$parsed->format('Y-m-d'),'amount'=>round((float)$amount,2),'reference'=>$reference,'description'=>$description?:null];}fclose($fp);if(!$rows)throw new DomainException('The CSV contains no statement transactions.');$db->beginTransaction();$q=$db->prepare("INSERT INTO fee_reconciliation_batches(school_id,statement_name,statement_date,row_count,created_by) VALUES(?,?,?,?,?)");$q->execute([$school,$name,$date,count($rows),$uid]);$batch=(int)$db->lastInsertId();$insert=$db->prepare('INSERT INTO fee_reconciliation_lines(batch_id,school_id,line_number,transaction_date,amount,reference,description,matched_ledger_id,match_status) VALUES(?,?,?,?,?,?,?,?,?)');$lookup=$db->prepare("SELECT id,amount FROM school_fee_ledger WHERE school_id=? AND entry_type='payment' AND reference=? AND created_at BETWEEN DATE_SUB(CONCAT(?,' 00:00:00'),INTERVAL 7 DAY) AND DATE_ADD(CONCAT(?,' 23:59:59'),INTERVAL 7 DAY) ORDER BY id");$prior=$db->prepare("SELECT 1 FROM fee_reconciliation_lines x JOIN fee_reconciliation_batches b ON b.id=x.batch_id AND b.school_id=x.school_id WHERE x.school_id=? AND x.matched_ledger_id=? AND x.match_status='matched' LIMIT 1");$matched=0;$seenLedger=[];foreach($rows as $row){$lookup->execute([$school,$row['reference'],$row['date'],$row['date']]);$found=$lookup->fetchAll();$ledgerId=null;$status='unmatched';if(count($found)>1)$status='duplicate_reference';elseif(count($found)===1){if(abs((float)$found[0]['amount']-$row['amount'])>0.009)$status='amount_mismatch';else{$prior->execute([$school,$found[0]['id']]);if($prior->fetchColumn()||isset($seenLedger[(int)$found[0]['id']]))$status='duplicate_reference';else{$status='matched';$ledgerId=(int)$found[0]['id'];$seenLedger[$ledgerId]=true;$matched++;}}}$insert->execute([$batch,$school,$row['line'],$row['date'],$row['amount'],$row['reference'],$row['description'],$ledgerId,$status]);}$q=$db->prepare('UPDATE fee_reconciliation_batches SET matched_count=? WHERE id=? AND school_id=?');$q->execute([$matched,$batch,$school]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'import','fee_reconciliation_batch',$batch,json_encode(['school_id'=>$school,'row_count'=>count($rows),'matched_count'=>$matched],JSON_THROW_ON_ERROR)]);$db->commit();reconciliation_json(201,['ok'=>true,'message'=>'Statement imported. Matches are suggestions for review; no payment entries were created.','data'=>['batch_id'=>$batch,'row_count'=>count($rows),'matched_count'=>$matched]]);}
 $batch=filter_var($_POST['batch_id']??null,FILTER_VALIDATE_INT);if(!$batch)throw new DomainException('Choose a reconciliation batch.');$db->beginTransaction();$q=$db->prepare("SELECT * FROM fee_reconciliation_batches WHERE id=? AND school_id=? AND status='reviewing' FOR UPDATE");$q->execute([$batch,$school]);if(!$q->fetch())throw new DomainException('Only a statement batch under review can be changed.');
 if($action==='match_line'){$line=filter_var($_POST['line_id']??null,FILTER_VALIDATE_INT);$ledger=filter_var($_POST['ledger_id']??null,FILTER_VALIDATE_INT);$q=$db->prepare('SELECT * FROM fee_reconciliation_lines WHERE id=? AND batch_id=? AND school_id=? FOR UPDATE');$q->execute([$line,$batch,$school]);$row=$q->fetch();if(!$row||!$ledger)throw new DomainException('Choose a statement line and receipt.');if($row['match_status']==='matched')throw new DomainException('This statement line is already matched. Exclude it with a reason before selecting a replacement receipt.');$q=$db->prepare("SELECT id,amount,created_at FROM school_fee_ledger WHERE id=? AND school_id=? AND entry_type='payment' FOR UPDATE");$q->execute([$ledger,$school]);$entry=$q->fetch();if(!$entry||abs((float)$entry['amount']-(float)$row['amount'])>0.009||abs((strtotime($entry['created_at'])-strtotime($row['transaction_date']))/86400)>7)throw new DomainException('Select a same-school receipt with the same amount and a date within seven days.');$q=$db->prepare("SELECT 1 FROM fee_reconciliation_lines x JOIN fee_reconciliation_batches b ON b.id=x.batch_id AND b.school_id=x.school_id WHERE x.school_id=? AND x.matched_ledger_id=? AND x.match_status='matched' LIMIT 1");$q->execute([$school,$ledger]);if($q->fetchColumn())throw new DomainException('That receipt has already been matched in another statement line.');$db->prepare("UPDATE fee_reconciliation_lines SET matched_ledger_id=?,match_status='matched',review_note=NULL WHERE id=? AND batch_id=? AND school_id=?")->execute([$ledger,$line,$batch,$school]);}
 elseif($action==='ignore_line'){$line=filter_var($_POST['line_id']??null,FILTER_VALIDATE_INT);$note=trim((string)($_POST['review_note']??''));if(!$line||$note===''||mb_strlen($note)>255)throw new DomainException('Choose a statement line and enter a reason to exclude it.');$q=$db->prepare('SELECT id FROM fee_reconciliation_lines WHERE id=? AND batch_id=? AND school_id=? FOR UPDATE');$q->execute([$line,$batch,$school]);if(!$q->fetchColumn())throw new DomainException('Statement line not found.');$db->prepare("UPDATE fee_reconciliation_lines SET matched_ledger_id=NULL,match_status='ignored',review_note=? WHERE id=? AND batch_id=? AND school_id=?")->execute([$note,$line,$batch,$school]);}
 elseif($action==='complete'){$q=$db->prepare("SELECT COUNT(*) total,SUM(match_status IN ('matched','ignored')) reviewed,SUM(match_status='matched') matched FROM fee_reconciliation_lines WHERE batch_id=? AND school_id=?");$q->execute([$batch,$school]);$counts=$q->fetch();if((int)$counts['total']===0||(int)$counts['total']!==(int)$counts['reviewed'])throw new DomainException('Match every statement receipt or document why it should be excluded before completing.');$db->prepare("UPDATE fee_reconciliation_batches SET status='completed',matched_count=?,completed_by=?,completed_at=CURRENT_TIMESTAMP WHERE id=? AND school_id=? AND status='reviewing'")->execute([(int)$counts['matched'],$uid,$batch,$school]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'complete','fee_reconciliation_batch',$batch,json_encode(['school_id'=>$school,'row_count'=>(int)$counts['total'],'matched_count'=>(int)$counts['matched'],'ignored_count'=>(int)$counts['total']-(int)$counts['matched']],JSON_THROW_ON_ERROR)]);}
 else throw new DomainException('Choose a supported reconciliation action.');
 if($action!=='complete'){$q=$db->prepare('SELECT COUNT(*) total,SUM(match_status="matched") matched FROM fee_reconciliation_lines WHERE batch_id=? AND school_id=?');$q->execute([$batch,$school]);$counts=$q->fetch();$db->prepare('UPDATE fee_reconciliation_batches SET matched_count=? WHERE id=? AND school_id=?')->execute([(int)$counts['matched'],$batch,$school]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,$action,'fee_reconciliation_batch',$batch,json_encode(['school_id'=>$school,'line_id'=>(int)($_POST['line_id']??0),'ledger_id'=>$action==='match_line'?(int)($_POST['ledger_id']??0):null,'review_note'=>$action==='ignore_line'?trim((string)($_POST['review_note']??'')):null,'matched_count'=>(int)$counts['matched']],JSON_THROW_ON_ERROR)]);}$db->commit();reconciliation_json(200,['ok'=>true,'message'=>$action==='complete'?'Reconciliation completed. No fee ledger entries were changed.':'Statement line updated.','data'=>['batch_id'=>$batch]]);
}catch(DomainException $e){if($db->inTransaction())$db->rollBack();reconciliation_json(422,['ok'=>false,'message'=>$e->getMessage()]);}catch(PDOException $e){if($db->inTransaction())$db->rollBack();error_log('Fee reconciliation database error: '.$e->getMessage());reconciliation_json($e->getCode()==='23000'?409:500,['ok'=>false,'message'=>'The reconciliation could not be saved. Verify the latest fee migration.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Fee reconciliation request failed: '.$e->getMessage());reconciliation_json(500,['ok'=>false,'message'=>'The reconciliation request could not be completed.']);}
